const money=v=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(Number(v||0));
const date=v=>v?new Intl.DateTimeFormat('pt-BR',{timeZone:'America/Bahia',dateStyle:'short'}).format(new Date(String(v).length===10?`${v}T12:00:00-03:00`:v)):'—';
const datetime=v=>v?new Intl.DateTimeFormat('pt-BR',{timeZone:'America/Bahia',dateStyle:'short',timeStyle:'short'}).format(new Date(v)):'—';
const cap=v=>String(v||'').replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase());
const badgeClass=v=>{const x=String(v||'').toLowerCase();if(['concluida','resolvida','realizada','devolvido','confirmada','publicado','ativa','disponivel'].some(s=>x.includes(s)))return'badge green';if(['cancelada','critica','inativo','arquivada'].some(s=>x.includes(s)))return'badge red';if(['alta','aguardando','pendente','aberta','emprestada'].some(s=>x.includes(s)))return'badge orange';return'badge blue'};

function Modal({title,fields,initial,onClose,onSave,areas=[],saveLabel='Salvar'}){
 const [form,setForm]=useState(()=>{const z={};fields.forEach(f=>z[f.name]=initial?.[f.name]??f.default??(f.type==='checkbox'?false:''));return z});
 const [error,setError]=useState('');const [loading,setLoading]=useState(false);const set=(k,v)=>setForm(x=>({...x,[k]:v}));
 async function submit(e){e.preventDefault();setError('');setLoading(true);try{await onSave(form)}catch(e){setError(e.message)}finally{setLoading(false)}}
 const remaining=fields.some(f=>f.name==='valor_pago')?Math.max(Number(form.valor_total||0)-Number(form.valor_pago||0),0):null;
 return <div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)onClose()}}><form className="modal" onSubmit={submit}>
  <div className="modalhead"><h2>{title}</h2><button className="iconbtn" type="button" onClick={onClose}>×</button></div>
  <div className="modalbody"><div className="form-grid">{fields.map(f=><div className={`field ${f.full?'full':''}`} key={f.name}><label>{f.label}{f.required?' *':''}</label>{f.type==='textarea'?<textarea value={form[f.name]??''} onChange={e=>set(f.name,e.target.value)} required={f.required}/>:f.type==='select'?<select value={form[f.name]??''} onChange={e=>set(f.name,e.target.value)} required={f.required}><option value="">{f.placeholder||'Selecione'}</option>{(f.options||[]).map(o=><option key={String(o.value)} value={o.value}>{o.label}</option>)}</select>:f.type==='checkbox'?<label style={{display:'flex',gap:8,alignItems:'center'}}><input type="checkbox" checked={!!form[f.name]} onChange={e=>set(f.name,e.target.checked)}/>{f.checkboxLabel||'Sim'}</label>:<input type={f.type||'text'} value={form[f.name]??''} min={f.min} max={f.max} step={f.step} onChange={e=>set(f.name,e.target.value)} required={f.required}/>} {f.help&&<span className="helper">{f.help}</span>}</div>)}{form.area_id&&<div className="field full"><strong>Regras do espaço selecionado</strong><p className="notice-body">{areas.find(a=>a.id===form.area_id)?.regulamento||'Sem regulamento cadastrado.'}</p>{areas.find(a=>a.id===form.area_id)?.regras&&<p>Antecedência: {areas.find(a=>a.id===form.area_id).regras.antecedencia_horas||0}h. Limite mensal: {areas.find(a=>a.id===form.area_id).regras.limite_mensal||'sem limite'}. Cancelamento: até {areas.find(a=>a.id===form.area_id).regras.cancelamento_horas||0}h antes.</p>}</div>}{remaining!==null&&<div className="field full"><label>Valor restante</label><div className="successbox" style={{margin:0,fontSize:16,fontWeight:800}}>{money(remaining)}</div></div>}</div>{error&&<div className="errorbox">{error}</div>}</div>
  <div className="modalfoot"><button type="button" className="btn light" onClick={onClose}>Cancelar</button><button className="btn primary" disabled={loading}>{loading?'Salvando...':saveLabel}</button></div>
 </form></div>
}
function Card({title,subtitle,actions,children}){return <section className="card"><div className="cardhead"><div><h2>{title}</h2>{subtitle&&<p>{subtitle}</p>}</div><div className="actions">{actions}</div></div>{children}</section>}
function Empty(){return <div className="empty">Nenhum registro encontrado.</div>}
const Table=DataTable;

export default function Dashboard(){
 const [occurrence,setOccurrence]=useState(null),[runner,setRunner]=useState(null),[workOrder,setWorkOrder]=useState(null),[navSearch,setNavSearch]=useState(''),[favorite,setFavorite]=useState([]),[focused,setFocused]=useState(null);
 const router=useRouter();const [token,setToken]=useState('');const [me,setMe]=useState(null);const [page,setPage]=useState('painel');const [data,setData]=useState({});const [dash,setDash]=useState({metrics:{},alerts:[]});const [modal,setModal]=useState(null);const [notice,setNotice]=useState('');const [error,setError]=useState('');const [busy,setBusy]=useState(false);const [adminTab,setAdminTab]=useState('config');const [superData,setSuperData]=useState([]);
 const auth=useCallback(async(url,options={})=>{const t=localStorage.getItem('token');const cid=localStorage.getItem('condominio_id');const r=await fetch(url,{...options,headers:{...(options.body?{'Content-Type':'application/json'}:{}),...(cid?{'X-Condominio-Id':cid}:{}),...(options.headers||{}),Authorization:`Bearer ${t}`},cache:'no-store'});if(r.status===401){localStorage.removeItem('token');router.replace('/login');throw new Error('Sessão expirada.')}const d=await r.json().catch(()=>({}));if(!r.ok)throw new Error(d.error||'Erro na operação.');return d},[router]);
 const load=useCallback(async m=>{const d=await auth(`/api/data/${m}`);setData(x=>({...x,[m]:d.items||[]}));return d.items||[]},[auth]);
 const loadDashboard=useCallback(async()=>{const d=await auth('/api/dashboard');setDash(d)},[auth]);
 const deps={manutencoes:['manutencoes','inventario','fornecedores'],os:['os','inventario','fornecedores','manutencoes','materiais'],checklists:['checklists','inventario'],ocorrencias:['ocorrencias'],inventario:['inventario'],estoque:['materiais','movimentacoes'],ferramentas:['ferramentas','emprestimos'],cotacoes:['cotacoes'],fornecedores:['fornecedores'],documentos:['documentos','contratos','fornecedores'],unidades:['unidades','moradores'],reservas:['reservas','areas','unidades'],comunicados:['comunicados'],administracao:['configuracoes','usuarios','chaves'],superadmin:[]};
 const refresh=useCallback(async(p=page)=>{setBusy(true);setError('');try{if(p==='painel')await loadDashboard();else if(p==='superadmin'){const d=await auth('/api/superadmin/condominios');setSuperData(d.items||[])}else await Promise.all((deps[p]||[]).map(load))}catch(e){setError(e.message)}finally{setBusy(false)}},[page,load,loadDashboard]);
 useEffect(()=>{const t=localStorage.getItem('token');if(!t){router.replace('/login');return}setToken(t);auth('/api/me').then(d=>{setMe(d);try{setFavorite(JSON.parse(localStorage.getItem('favoritos:'+d.user.id)||'[]'))}catch{}if(!localStorage.getItem('condominio_id')&&d.condominio?.id)localStorage.setItem('condominio_id',d.condominio.id)}).catch(()=>{})},[auth,router]);
 useEffect(()=>{if(me)refresh(page)},[me,page]);
 const go=(p,id)=>{setFocused(id||null);if(id&&p==='os')setWorkOrder(id);if(p==='administracao'&&me?.user?.perfil!=='admin'&&!me?.user?.is_superadmin)return;if(p==='superadmin'&&!me?.user?.is_superadmin)return;setPage(p);setNotice('');setError('')};
 const logout=async()=>{try{await auth('/api/auth/logout',{method:'POST'})}catch{}localStorage.removeItem('token');localStorage.removeItem('condominio_id');router.replace('/login')};
 async function switchCondo(cid){localStorage.setItem('condominio_id',cid);setBusy(true);setError('');try{const d=await auth('/api/me');setMe(d);setData({});setDash({metrics:{},alerts:[]});setPage('painel');await loadDashboard()}catch(e){setError(e.message)}finally{setBusy(false)}}
 async function saveCondo(payload){const d=await auth('/api/superadmin/condominios',{method:'POST',body:JSON.stringify(payload)});setNotice('Condomínio criado com sucesso.');setModal(null);const list=await auth('/api/superadmin/condominios');setSuperData(list.items||[]);return d}
 async function updateCondo(payload){const d=await auth('/api/superadmin/condominios',{method:'PATCH',body:JSON.stringify(payload)});setNotice('Condomínio atualizado.');const list=await auth('/api/superadmin/condominios');setSuperData(list.items||[]);return d}
 async function post(module,payload){const d=await auth(`/api/data/${module}`,{method:'POST',body:JSON.stringify(payload)});setNotice('Registro salvo com sucesso.');setModal(null);await refresh();return d}
 async function patch(module,payload){const d=await auth(`/api/data/${module}`,{method:'PATCH',body:JSON.stringify(payload)});setNotice('Alteração salva com sucesso.');setModal(null);await refresh();return d}
 const opts=(arr,label='nome')=>(arr||[]).map(x=>({value:x.id,label:x[label]||x.descricao||x.razao_social||x.unidade}));
 const openNew=(kind,title,fields,module)=>setModal({kind,title,fields,module,initial:null,onSave:f=>post(module,f)});
 const openEdit=(title,fields,module,item)=>setModal({title,fields,module,initial:item,onSave:f=>patch(module,{...f,id:item.id})});
 async function openReport(type){try{setBusy(true);const r=await fetch(`/api/reports/${type}`,{headers:{Authorization:`Bearer ${localStorage.getItem('token')}`,...(localStorage.getItem('condominio_id')?{'X-Condominio-Id':localStorage.getItem('condominio_id')}:{})}});if(!r.ok){const d=await r.json().catch(()=>({}));throw new Error(d.error||'Falha ao gerar relatório')}const b=await r.blob();const url=URL.createObjectURL(b);window.open(url,'_blank');setTimeout(()=>URL.revokeObjectURL(url),60000)}catch(e){setError(e.message)}finally{setBusy(false)}}
 const condo=me?.condominio||{};const systemName=condo.nome_sistema||'Gestão Operacional de Condomínios';const brand=condo.cor_primaria||'#2563eb';const [ptitle,psub]=pageMeta[page]||['',''];
 const formFields={
  inventario:[{name:'patrimonio',label:'Patrimônio'},{name:'descricao',label:'Descrição',required:true},{name:'categoria',label:'Categoria'},{name:'quantidade',label:'Quantidade',type:'number',step:'0.01',default:1},{name:'unidade',label:'Unidade',default:'un'},{name:'localizacao',label:'Localização'},{name:'estado_conservacao',label:'Estado',type:'select',default:'bom',options:['novo','bom','regular','ruim'].map(x=>({value:x,label:cap(x)}))},{name:'valor_aquisicao',label:'Valor de aquisição',type:'number',step:'0.01'},{name:'data_aquisicao',label:'Data de aquisição',type:'date'},{name:'observacoes',label:'Observações',type:'textarea',full:true}],
  material:[{name:'codigo',label:'Código'},{name:'nome',label:'Material',required:true},{name:'categoria',label:'Categoria'},{name:'unidade',label:'Unidade',default:'un'},{name:'estoque_atual',label:'Estoque atual',type:'number',step:'0.01',default:0},{name:'estoque_minimo',label:'Estoque mínimo',type:'number',step:'0.01',default:0},{name:'localizacao',label:'Localização'},{name:'fornecedor',label:'Fornecedor'},{name:'observacoes',label:'Observações',type:'textarea',full:true}],
  fornecedor:[{name:'razao_social',label:'Razão social',required:true},{name:'nome_fantasia',label:'Nome fantasia'},{name:'cnpj',label:'CNPJ'},{name:'categoria',label:'Categoria'},{name:'contato',label:'Contato'},{name:'telefone',label:'Telefone'},{name:'email',label:'E-mail',type:'email'},{name:'avaliacao',label:'Avaliação (1 a 5)',type:'number',min:1,max:5},{name:'observacoes',label:'Observações',type:'textarea',full:true}],
  ocorrencia:[{name:'titulo',label:'Título',required:true},{name:'categoria',label:'Categoria'},{name:'prioridade',label:'Prioridade',type:'select',default:'media',options:['baixa','media','alta','critica'].map(x=>({value:x,label:cap(x)}))},{name:'unidade',label:'Unidade'},{name:'responsavel',label:'Responsável'},{name:'descricao',label:'Descrição',type:'textarea',full:true}],
  comunicado:[{name:'titulo',label:'Título',required:true},{name:'publico',label:'Público',type:'select',default:'todos',options:['todos','moradores','equipe','administracao'].map(x=>({value:x,label:cap(x)}))},{name:'mensagem',label:'Mensagem',type:'textarea',required:true,full:true},{name:'publicado',label:'Publicar agora',type:'checkbox',default:true,full:true}],
 };
 function reservationFields(){return [{name:'area_id',label:'Área reservada',type:'select',required:true,options:opts(data.areas)},{name:'unidade_id',label:'Unidade (opcional)',type:'select',options:opts(data.unidades,'unidade')},{name:'responsavel',label:'Solicitante / responsável',required:true},{name:'email_solicitante',label:'E-mail do solicitante',type:'text',required:true,help:'Para mais de um destinatário, separe os e-mails com ;  Ex.: cliente@email.com; administracao@condominio.com'},{name:'whatsapp_solicitante',label:'WhatsApp do solicitante',type:'tel',help:'Informe DDD + número. Ex.: 71999999999'},{name:'tipo_evento',label:'Tipo de evento',required:true},{name:'status',label:'Status',type:'select',default:'confirmada',options:[{value:'confirmada',label:'Confirmada'},{value:'realizada',label:'Realizada'},{value:'cancelada',label:'Cancelada'}]},{name:'inicio_local',label:'Data e hora de início',type:'datetime-local',required:true},{name:'fim_local',label:'Data e hora de término',type:'datetime-local',required:true},{name:'valor_total',label:'Valor da reserva',type:'number',step:'0.01',min:0,default:0},{name:'valor_pago',label:'Valor pago',type:'number',step:'0.01',min:0,default:0},{name:'aceite',label:'Li e aceito as regras do espaço',type:'checkbox',default:false,full:true},{name:'observacoes',label:'Observações',type:'textarea',full:true}].map(f=>f.name==='inicio_local'?{...f,name:'inicio'}:f.name==='fim_local'?{...f,name:'fim'}:f)}
 function reservationInitial(r){return {...r,inicio:r.inicio_local,fim:r.fim_local}}
 function openReservationWhatsApp(r){
  setError('');setNotice('');
  let phone=String(r.whatsapp_solicitante||'').replace(/\D/g,'');
  if(!phone){setError('Cadastre o WhatsApp do solicitante antes de enviar a mensagem.');return}
  if(phone.length===10||phone.length===11)phone=`55${phone}`;
  if(!/^55\d{10,11}$/.test(phone)){setError('O WhatsApp cadastrado é inválido. Informe DDD + número.');return}
  const inicio=String(r.inicio_formatado||'').split(' '),fim=String(r.fim_formatado||'').split(' ');
  const msg=[
   `Olá, ${r.responsavel}!`,
   '',
   `Seguem os dados da sua reserva no ${condo.nome||'condomínio'}.`,
   '',
   `Área: ${r.area||'—'}`,
   `Evento: ${r.tipo_evento||'—'}`,
   `Data: ${inicio[0]||'—'}`,
   `Horário: ${inicio[1]||'—'} às ${fim[1]||'—'}`,
   `Status: ${cap(r.status)}`,
   '',
   `Valor total: ${money(r.valor_total)}`,
   `Valor pago: ${money(r.valor_pago)}`,
   `Valor restante: ${money(r.valor_restante)}`,
   ...(r.observacoes?['',`Observações: ${r.observacoes}`]:[]),
   '',
   'Aguardamos você!'
  ].join('\n');
  window.open(`https://wa.me/${phone}?text=${encodeURIComponent(msg)}`,'_blank','noopener,noreferrer');
 }
 function content(){
  if(['alertas','plantao','custos','acessos','recuperacoes'].includes(page))return <OperationsPanel key={page+condo.id} page={page} auth={auth} go={go} user={me?.user}/>;
  if(page==='implantacao')return <SetupGuide auth={auth} go={go}/>;
  if(page==='comunicados')return <NoticeManager auth={auth} user={me?.user}/>;
  if(page==='painel')return <Panel dash={dash} go={go}/>;
  if(page==='inventario')return <Card title="Itens do inventário" actions={<button className="btn primary small" onClick={()=>openNew('inventario','Novo item',formFields.inventario,'inventario')}><Plus size={15}/>Novo item</button>}><Table rows={focused?data.inventario?.filter(r=>r.id===focused):data.inventario} columns={[{key:'patrimonio',label:'Patrimônio'},{key:'descricao',label:'Descrição',render:r=><span className="strong">{r.descricao}</span>},{key:'categoria',label:'Categoria'},{key:'quantidade',label:'Qtd.'},{key:'localizacao',label:'Localização'},{key:'estado_conservacao',label:'Estado',render:r=><span className={badgeClass(r.estado_conservacao)}>{cap(r.estado_conservacao)}</span>},{key:'valor_aquisicao',label:'Valor',render:r=>r.valor_aquisicao?money(r.valor_aquisicao):'—'}]}/></Card>;
  if(page==='fornecedores')return <Card title="Fornecedores" actions={<button className="btn primary small" onClick={()=>openNew('fornecedor','Novo fornecedor',formFields.fornecedor,'fornecedores')}><Plus size={15}/>Novo fornecedor</button>}><Table rows={data.fornecedores} columns={[{key:'razao_social',label:'Razão social',render:r=><div className="stack"><span className="strong">{r.razao_social}</span><span className="muted">{r.nome_fantasia}</span></div>},{key:'cnpj',label:'CNPJ'},{key:'categoria',label:'Categoria'},{key:'contato',label:'Contato'},{key:'telefone',label:'Telefone'},{key:'email',label:'E-mail'},{key:'avaliacao',label:'Avaliação',render:r=>r.avaliacao?`${r.avaliacao}/5`:'—'}]}/></Card>;
  if(page==='manutencoes')return <Card title="Planos de manutenção" actions={<button className="btn primary small" onClick={()=>openNew('man','Nova manutenção',[{name:'titulo',label:'Título',required:true},{name:'categoria',label:'Categoria'},{name:'inventario_id',label:'Item de inventário',type:'select',options:opts(data.inventario,'descricao')},{name:'fornecedor_id',label:'Fornecedor',type:'select',options:opts(data.fornecedores,'razao_social')},{name:'periodicidade_dias',label:'Periodicidade (dias)',type:'number',default:30},{name:'proxima_execucao',label:'Próxima execução',type:'date',required:true},{name:'ultima_execucao',label:'Última execução',type:'date'},{name:'custo_estimado',label:'Custo estimado',type:'number',step:'0.01'},{name:'instrucoes',label:'Instruções',type:'textarea',full:true}],'manutencoes')}><Plus size={15}/>Novo plano</button>}><Table rows={focused?data.manutencoes?.filter(r=>r.id===focused):data.manutencoes} columns={[{key:'titulo',label:'Título',render:r=><span className="strong">{r.titulo}</span>},{key:'categoria',label:'Categoria'},{key:'inventario',label:'Item'},{key:'periodicidade_dias',label:'Periodicidade',render:r=>`${r.periodicidade_dias} dias`},{key:'proxima_execucao',label:'Próxima',render:r=>date(r.proxima_execucao)},{key:'custo_estimado',label:'Custo',render:r=>r.custo_estimado?money(r.custo_estimado):'—'}]}/></Card>;
  if(page==='os')return <Card title="Ordens de serviço" actions={<button className="btn primary small" onClick={()=>openNew('os','Nova ordem de serviço',[{name:'titulo',label:'Título',required:true},{name:'prioridade',label:'Prioridade',type:'select',default:'media',options:['baixa','media','alta','critica'].map(x=>({value:x,label:cap(x)}))},{name:'responsavel',label:'Responsável'},{name:'prazo',label:'Prazo',type:'datetime-local'},{name:'inventario_id',label:'Item de inventário',type:'select',options:opts(data.inventario,'descricao')},{name:'fornecedor_id',label:'Fornecedor',type:'select',options:opts(data.fornecedores,'razao_social')},{name:'descricao',label:'Descrição',type:'textarea',full:true},{name:'observacoes',label:'Observações',type:'textarea',full:true}],'os')}><Plus size={15}/>Abrir OS</button>}><Table rows={focused?data.os?.filter(r=>r.id===focused):data.os} columns={[{key:'numero_os',label:'OS',render:r=><span className="strong">{r.numero_os}</span>},{key:'titulo',label:'Título'},{key:'prioridade',label:'Prioridade',render:r=><span className={badgeClass(r.prioridade)}>{cap(r.prioridade)}</span>},{key:'status',label:'Status',render:r=><span className={badgeClass(r.status)}>{cap(r.status)}</span>},{key:'responsavel',label:'Responsável'},{key:'data_abertura',label:'Abertura',render:r=>datetime(r.data_abertura)},{key:'prazo',label:'Prazo',render:r=>datetime(r.prazo)}]} actions={r=><div className="actions">{r.status==='aberta'&&<button className="btn light small" onClick={()=>patch('os',{id:r.id,status:'em_andamento'})}>Iniciar</button>}<button className="btn primary small" onClick={()=>setWorkOrder(r.id)}>Detalhes e execução</button></div>}/></Card>;
  if(page==='ocorrencias')return <Card title="Ocorrências" actions={<button className="btn primary small" onClick={()=>openNew('oc','Nova ocorrência',formFields.ocorrencia,'ocorrencias')}><Plus size={15}/>Registrar</button>}><Table rows={data.ocorrencias} columns={[{key:'protocolo',label:'Protocolo',render:r=><span className="strong">{r.protocolo}</span>},{key:'titulo',label:'Título'},{key:'prioridade',label:'Prioridade',render:r=><span className={badgeClass(r.prioridade)}>{cap(r.prioridade)}</span>},{key:'status',label:'Status',render:r=><span className={badgeClass(r.status)}>{cap(r.status)}</span>},{key:'unidade',label:'Unidade'},{key:'responsavel',label:'Responsável'},{key:'criado_em',label:'Data',render:r=>datetime(r.criado_em)}]} actions={r=><div className="actions"><button className="btn light small" onClick={()=>setOccurrence(r)}>Detalhes</button>{!['resolvida','arquivada'].includes(r.status)?<button className="btn success small" onClick={()=>patch('ocorrencias',{id:r.id,status:'resolvida'})}>Resolver</button>:null}</div>}/></Card>;
  if(page==='checklists')return <><Card title="Modelos de checklist" actions={<button className="btn primary small" onClick={()=>openNew('check','Novo checklist',[{name:'nome',label:'Nome',required:true},{name:'area',label:'Área'},{name:'periodicidade',label:'Periodicidade',type:'select',default:'diario',options:['diario','semanal','mensal','livre'].map(x=>({value:x,label:cap(x)}))},{name:'exige_foto',label:'Exigir foto em todos os itens',type:'checkbox'},{name:'itens_texto',label:'Itens (um por linha)',type:'textarea',full:true}].map(x=>x),'checklists')}><Plus size={15}/>Novo checklist</button>}><Table rows={data.checklists} columns={[{key:'nome',label:'Nome',render:r=><span className="strong">{r.nome}</span>},{key:'area',label:'Área'},{key:'periodicidade',label:'Periodicidade',render:r=>cap(r.periodicidade)},{key:'itens',label:'Itens',render:r=>(r.itens||[]).map(x=>x.descricao).join(', ')||'—'}]} actions={r=><button className="btn primary small" onClick={()=>setRunner(r)}>Executar</button>}/></Card><ChecklistHistory key={notice} auth={auth}/></>;
  if(page==='estoque')return <div className="grid2" style={{gridTemplateColumns:'1fr'}}><Card title="Materiais" actions={<><button className="btn light small" onClick={()=>openNew('mov','Movimentar estoque',[{name:'material_id',label:'Material',type:'select',required:true,options:opts(data.materiais)},{name:'tipo',label:'Tipo',type:'select',default:'entrada',options:[{value:'entrada',label:'Entrada'},{value:'saida',label:'Saída'}]},{name:'quantidade',label:'Quantidade',type:'number',step:'0.01',required:true},{name:'destino_origem',label:'Origem / destino'},{name:'documento',label:'Documento'},{name:'observacoes',label:'Observações',type:'textarea',full:true}],'movimentacoes')}>Movimentar</button><button className="btn primary small" onClick={()=>openNew('mat','Novo material',formFields.material,'materiais')}><Plus size={15}/>Novo material</button></>}><Table rows={focused?data.materiais?.filter(r=>r.id===focused):data.materiais} columns={[{key:'codigo',label:'Código'},{key:'nome',label:'Material',render:r=><span className="strong">{r.nome}</span>},{key:'categoria',label:'Categoria'},{key:'estoque_atual',label:'Atual'},{key:'estoque_minimo',label:'Mínimo'},{key:'unidade',label:'Un.'},{key:'localizacao',label:'Localização'},{key:'alerta',label:'Situação',render:r=><span className={Number(r.estoque_atual)<=Number(r.estoque_minimo)?'badge red':'badge green'}>{Number(r.estoque_atual)<=Number(r.estoque_minimo)?'Repor':'OK'}</span>}]} /></Card><Card title="Últimas movimentações"><Table rows={data.movimentacoes} columns={[{key:'material',label:'Material'},{key:'tipo',label:'Tipo',render:r=><span className={r.tipo==='saida'?'badge orange':'badge green'}>{cap(r.tipo)}</span>},{key:'quantidade',label:'Quantidade'},{key:'saldo_novo',label:'Saldo'},{key:'destino_origem',label:'Origem / destino'},{key:'criado_em',label:'Data',render:r=>datetime(r.criado_em)}]}/></Card></div>;
  if(page==='ferramentas')return <div className="grid2" style={{gridTemplateColumns:'1fr'}}><Card title="Ferramentas" actions={<button className="btn primary small" onClick={()=>openNew('fer','Nova ferramenta',[{name:'codigo',label:'Código'},{name:'nome',label:'Nome',required:true},{name:'categoria',label:'Categoria'},{name:'marca',label:'Marca'},{name:'modelo',label:'Modelo'},{name:'numero_serie',label:'Nº de série'},{name:'estado_conservacao',label:'Estado',type:'select',default:'bom',options:['novo','bom','regular','ruim'].map(x=>({value:x,label:cap(x)}))},{name:'localizacao',label:'Localização'},{name:'observacoes',label:'Observações',type:'textarea',full:true}],'ferramentas')}><Plus size={15}/>Nova ferramenta</button>}><Table rows={data.ferramentas} columns={[{key:'codigo',label:'Código'},{key:'nome',label:'Ferramenta',render:r=><span className="strong">{r.nome}</span>},{key:'categoria',label:'Categoria'},{key:'status',label:'Status',render:r=><span className={badgeClass(r.status)}>{cap(r.status)}</span>},{key:'responsavel_atual',label:'Responsável'},{key:'localizacao',label:'Localização'}]} actions={r=>r.status==='disponivel'?<button className="btn light small" onClick={()=>openNew('emp','Retirar ferramenta',[{name:'ferramenta_id',label:'Ferramenta',type:'select',default:r.id,options:[{value:r.id,label:r.nome}],required:true},{name:'responsavel',label:'Responsável',required:true},{name:'setor',label:'Setor'},{name:'previsao_devolucao',label:'Previsão de devolução',type:'datetime-local'},{name:'observacoes',label:'Observações',type:'textarea',full:true}],'emprestimos')}>Retirar</button>:null}/></Card><Card title="Empréstimos"><Table rows={focused?data.emprestimos?.filter(r=>r.id===focused):data.emprestimos} columns={[{key:'ferramenta',label:'Ferramenta'},{key:'responsavel',label:'Responsável'},{key:'setor',label:'Setor'},{key:'data_retirada',label:'Retirada',render:r=>datetime(r.data_retirada)},{key:'previsao_devolucao',label:'Previsão',render:r=>datetime(r.previsao_devolucao)},{key:'status',label:'Status',render:r=><span className={badgeClass(r.status)}>{cap(r.status)}</span>}]} actions={r=>r.status==='aberto'?<button className="btn success small" onClick={()=>patch('emprestimos',{id:r.id,observacoes_devolucao:''})}><RotateCcw size={14}/>Devolver</button>:null}/></Card></div>;
  if(page==='cotacoes')return <Card title="Cotações" actions={<button className="btn primary small" onClick={()=>openNew('cot','Nova cotação',[{name:'titulo',label:'Título',required:true},{name:'item1',label:'Item principal',required:true},{name:'quantidade1',label:'Quantidade',type:'number',step:'0.01',default:1},{name:'unidade1',label:'Unidade',default:'un'}],'cotacoes')}><Plus size={15}/>Nova cotação</button>}><Table rows={data.cotacoes} columns={[{key:'numero',label:'Número',render:r=><span className="strong">{r.numero}</span>},{key:'titulo',label:'Título'},{key:'status',label:'Status',render:r=><span className={badgeClass(r.status)}>{cap(r.status)}</span>},{key:'itens',label:'Itens',render:r=>(r.itens||[]).map(x=>`${x.descricao} (${x.quantidade} ${x.unidade})`).join(', ')||'—'},{key:'criado_em',label:'Criada em',render:r=>datetime(r.criado_em)}]}/></Card>;
  if(page==='documentos')return <div className="grid2" style={{gridTemplateColumns:'1fr'}}><Card title="Documentos" actions={<button className="btn primary small" onClick={()=>openNew('doc','Novo documento',[{name:'titulo',label:'Título',required:true},{name:'categoria',label:'Categoria'},{name:'numero',label:'Número'},{name:'emissao',label:'Emissão',type:'date'},{name:'validade',label:'Validade',type:'date'},{name:'fornecedor_id',label:'Fornecedor',type:'select',options:opts(data.fornecedores,'razao_social')},{name:'observacoes',label:'Observações',type:'textarea',full:true}],'documentos')}><Plus size={15}/>Novo documento</button>}><Table rows={focused?data.documentos?.filter(r=>r.id===focused):data.documentos} columns={[{key:'titulo',label:'Título',render:r=><span className="strong">{r.titulo}</span>},{key:'categoria',label:'Categoria'},{key:'numero',label:'Número'},{key:'emissao',label:'Emissão',render:r=>date(r.emissao)},{key:'validade',label:'Validade',render:r=>date(r.validade)},{key:'fornecedor',label:'Fornecedor'}]}/></Card><Card title="Contratos" actions={<button className="btn primary small" onClick={()=>openNew('con','Novo contrato',[{name:'titulo',label:'Título',required:true},{name:'fornecedor_id',label:'Fornecedor',type:'select',options:opts(data.fornecedores,'razao_social')},{name:'inicio',label:'Início',type:'date'},{name:'fim',label:'Fim',type:'date'},{name:'valor_mensal',label:'Valor mensal',type:'number',step:'0.01'},{name:'reajuste',label:'Reajuste'},{name:'observacoes',label:'Observações',type:'textarea',full:true}],'contratos')}><Plus size={15}/>Novo contrato</button>}><Table rows={data.contratos} columns={[{key:'titulo',label:'Título',render:r=><span className="strong">{r.titulo}</span>},{key:'fornecedor',label:'Fornecedor'},{key:'inicio',label:'Início',render:r=>date(r.inicio)},{key:'fim',label:'Fim',render:r=>date(r.fim)},{key:'valor_mensal',label:'Valor mensal',render:r=>r.valor_mensal?money(r.valor_mensal):'—'},{key:'reajuste',label:'Reajuste'}]}/></Card></div>;
  if(page==='unidades')return <div className="grid2" style={{gridTemplateColumns:'1fr'}}><Card title="Unidades" actions={<button className="btn primary small" onClick={()=>openNew('uni','Nova unidade',[{name:'bloco',label:'Bloco'},{name:'unidade',label:'Unidade',required:true},{name:'tipo',label:'Tipo',default:'apartamento'},{name:'observacoes',label:'Observações',type:'textarea',full:true}],'unidades')}><Plus size={15}/>Nova unidade</button>}><Table rows={data.unidades} columns={[{key:'bloco',label:'Bloco'},{key:'unidade',label:'Unidade',render:r=><span className="strong">{r.unidade}</span>},{key:'tipo',label:'Tipo'},{key:'moradores',label:'Moradores'}]}/></Card><Card title="Moradores" actions={<button className="btn primary small" onClick={()=>openNew('mor','Novo morador',[{name:'unidade_id',label:'Unidade',type:'select',required:true,options:opts(data.unidades,'unidade')},{name:'nome',label:'Nome',required:true},{name:'tipo',label:'Tipo',type:'select',default:'morador',options:['proprietario','morador','inquilino','dependente'].map(x=>({value:x,label:cap(x)}))},{name:'telefone',label:'Telefone'},{name:'email',label:'E-mail',type:'email'},{name:'veiculo',label:'Veículo'}],'moradores')}><Plus size={15}/>Novo morador</button>}><Table rows={data.moradores} columns={[{key:'nome',label:'Nome',render:r=><span className="strong">{r.nome}</span>},{key:'unidade',label:'Unidade',render:r=>`${r.bloco?`${r.bloco} / `:''}${r.unidade}`},{key:'tipo',label:'Tipo'},{key:'telefone',label:'Telefone'},{key:'email',label:'E-mail'},{key:'veiculo',label:'Veículo'}]}/></Card></div>;
  if(page==='reservas')return <div className="grid2" style={{gridTemplateColumns:'1fr'}}><Card title="Reservas" subtitle="Valores, pagamentos, lembrete por e-mail para um ou mais destinatários e envio manual pelo WhatsApp." actions={<><button className="btn light small" onClick={()=>openNew('area','Nova área reservável',[{name:'nome',label:'Nome da área',required:true},{name:'capacidade',label:'Capacidade',type:'number'},{name:'valor_taxa',label:'Taxa padrão',type:'number',step:'0.01'},{name:'regulamento',label:'Regulamento',type:'textarea',full:true}],'areas')}><Plus size={15}/>Área</button><button className="btn primary small" onClick={()=>openNew('res','Nova reserva',reservationFields(),'reservas')}><Plus size={15}/>Cadastrar reserva</button></>}><Table rows={data.reservas} columns={[{key:'area',label:'Área',render:r=><div className="stack"><span className="strong">{r.area}</span><span className="muted">{r.tipo_evento||'Evento não informado'}</span></div>},{key:'responsavel',label:'Solicitante',render:r=><div className="stack"><span>{r.responsavel}</span><span className="muted">{r.email_solicitante||'Sem e-mail'}</span><span className="muted">{r.whatsapp_solicitante||'Sem WhatsApp'}</span></div>},{key:'inicio',label:'Data / horário',render:r=><div className="stack"><span>{r.inicio_formatado}</span><span className="muted">até {r.fim_formatado}</span></div>},{key:'status',label:'Status',render:r=><span className={badgeClass(r.status)}>{cap(r.status)}</span>},{key:'valor_total',label:'Valor total',render:r=><span className="money strong">{money(r.valor_total)}</span>},{key:'valor_pago',label:'Pago',render:r=><span className="money">{money(r.valor_pago)}</span>},{key:'valor_restante',label:'A pagar',render:r=><span className={`money strong ${Number(r.valor_restante)>0?'':'muted'}`}>{money(r.valor_restante)}</span>}]} actions={r=><div className="actions"><button className="btn light small" onClick={()=>openEdit('Alterar reserva',reservationFields(),'reservas',reservationInitial(r))}><Pencil size={14}/>Alterar</button><button className="btn success small" onClick={()=>openReservationWhatsApp(r)} title={r.whatsapp_solicitante?'Abrir WhatsApp com a mensagem da reserva':'Cadastre o WhatsApp do solicitante'}><MessageCircle size={14}/>WhatsApp</button></div>}/></Card></div>;
  if(page==='comunicados')return <Card title="Comunicados" actions={<button className="btn primary small" onClick={()=>openNew('com','Novo comunicado',formFields.comunicado,'comunicados')}><Plus size={15}/>Novo comunicado</button>}><Table rows={data.comunicados} columns={[{key:'titulo',label:'Título',render:r=><span className="strong">{r.titulo}</span>},{key:'publico',label:'Público',render:r=>cap(r.publico)},{key:'publicado',label:'Situação',render:r=><span className={r.publicado?'badge green':'badge orange'}>{r.publicado?'Publicado':'Rascunho'}</span>},{key:'criado_em',label:'Criado em',render:r=>datetime(r.criado_em)},{key:'mensagem',label:'Mensagem',render:r=><span>{String(r.mensagem).slice(0,100)}{String(r.mensagem).length>100?'…':''}</span>} ]}/></Card>;
  if(page==='relatorios')return <Reports openReport={openReport}/>;
  if(page==='administracao')return <Admin data={data} tab={adminTab} setTab={setAdminTab} openNew={openNew} openEdit={openEdit} patch={patch} me={me}/>;
  if(page==='superadmin')return <SuperAdmin rows={superData} onNew={()=>setModal({title:'Novo condomínio',fields:[{name:'nome',label:'Nome do condomínio',required:true},{name:'cnpj',label:'CNPJ',required:true},{name:'razao_social',label:'Razão social'},{name:'responsavel',label:'Responsável'},{name:'email',label:'E-mail',type:'email'},{name:'telefone',label:'Telefone / WhatsApp'},{name:'endereco',label:'Endereço',full:true},{name:'plano',label:'Plano',type:'select',default:'profissional',options:[{value:'basico',label:'Básico'},{value:'profissional',label:'Profissional'},{value:'premium',label:'Premium'}]},{name:'limite_usuarios',label:'Limite de usuários',type:'number'},{name:'admin_nome',label:'Administrador inicial'},{name:'admin_email',label:'E-mail do administrador',type:'email'},{name:'admin_senha',label:'Senha inicial',type:'password',help:'Obrigatória se o e-mail ainda não existir na plataforma.'}],onSave:saveCondo})} onEdit={r=>setModal({title:'Alterar condomínio',fields:[{name:'nome',label:'Nome',required:true},{name:'razao_social',label:'Razão social'},{name:'responsavel',label:'Responsável'},{name:'email',label:'E-mail',type:'email'},{name:'telefone',label:'Telefone'},{name:'endereco',label:'Endereço',full:true},{name:'plano',label:'Plano',type:'select',options:[{value:'basico',label:'Básico'},{value:'profissional',label:'Profissional'},{value:'premium',label:'Premium'}]},{name:'limite_usuarios',label:'Limite de usuários',type:'number'},{name:'status',label:'Status',type:'select',options:[{value:'ativo',label:'Ativo'},{value:'suspenso',label:'Suspenso'},{value:'inativo',label:'Inativo'}]}],initial:r,onSave:f=>updateCondo({...f,id:r.id})})}/>;
  return null
 }
 return <div className="app" style={{'--brand':brand,'--brand-soft':`${brand}12`}}><header className="topbar"><div className="brandbox">{condo.logo_data_url?<img src={condo.logo_data_url} alt="Logo" style={{width:40,height:40,objectFit:'contain',borderRadius:10}}/>:<div className="brandmark">GC</div>}<div className="brandtext"><strong>{systemName}</strong><span>{condo.nome||''}</span></div></div><div className="top-actions">{me?.condominios?.length>1&&<select className="tenant-select" value={condo.id||''} onChange={e=>switchCondo(e.target.value)}>{me.condominios.filter(x=>x.status==='ativo').map(c=><option key={c.condominio_id} value={c.condominio_id}>{c.nome}</option>)}</select>}<button className="btn light small" onClick={()=>refresh()} disabled={busy}><RefreshCw size={14}/>{busy?'Atualizando...':'Atualizar'}</button><div className="userchip"><div className="avatar">{me?.user?.nome?.[0]?.toUpperCase()||'U'}</div><div className="info"><strong>{me?.user?.nome}</strong><span>{me?.user?.is_superadmin?'Super Administrador':cap(me?.user?.perfil||'Usuário')}</span></div></div><button className="btn light small" onClick={logout}><LogOut size={14}/>Sair</button></div></header>
 <div className="mobiletabs">{NAV.flatMap(x=>x.items).filter(x=>!x[3]||(x[3]==='admin'&&(me?.user?.perfil==='admin'||me?.user?.is_superadmin))||(x[3]==='super'&&me?.user?.is_superadmin)).map(([k,l])=><button key={k} className={page===k?'active':''} onClick={()=>go(k)}>{l}</button>)}</div>
 <div className="frame"><aside className="sidebar"><label className="field nav-search">Buscar módulo<input value={navSearch} onChange={e=>setNavSearch(e.target.value)} placeholder="Reservas, estoque..."/></label>{favorite.length>0&&<div className="navgroup"><div className="navtitle">FAVORITOS</div>{favorite.map(k=><button className="navitem" key={k} onClick={()=>go(k)}>{pageMeta[k]?.[0]}</button>)}</div>}{NAV.map(group=><div className="navgroup" key={group.g}><div className="navtitle">{group.g}</div>{group.items.filter(x=>!x[3]||(x[3]==='admin'&&(me?.user?.perfil==='admin'||me?.user?.is_superadmin))||(x[3]==='super'&&me?.user?.is_superadmin)).filter(([,l])=>l.toLowerCase().includes(navSearch.toLowerCase())).map(([k,l,Icon])=><button key={k} className={`navitem ${page===k?'active':''}`} onClick={()=>go(k)}><Icon/>{l}</button>)}</div>)}</aside><main className="main"><div className="pagehead"><div><h1>{ptitle}</h1><p>{psub}</p></div><div className="actions"><button className="btn light small" onClick={()=>{const f=favorite.includes(page)?favorite.filter(k=>k!==page):[...favorite,page];setFavorite(f);localStorage.setItem('favoritos:'+me?.user?.id,JSON.stringify(f))}}>{favorite.includes(page)?'Remover favorito':'Favoritar módulo'}</button></div></div>{notice&&<div className="successbox">{notice}</div>}{error&&<div className="errorbox">{error}</div>}{focused&&<button className="btn light small" onClick={()=>setFocused(null)}>Mostrar todos os registros</button>}{page==='reservas'&&<ReservationTools auth={auth} areas={data.areas||[]} reservations={data.reservas||[]} user={me?.user} onSaved={()=>refresh()}/>}{content()}</main></div>
 {occurrence&&<Dialog title={occurrence.titulo} onClose={()=>setOccurrence(null)}><p>{occurrence.descricao}</p><Attachments value={occurrence.anexos?.fotos||[]} readOnly/></Dialog>}{runner&&<ChecklistRunner model={runner} auth={auth} inventory={data.inventario||[]} onClose={()=>setRunner(null)} onSaved={m=>{setNotice(m);refresh()}}/>}{workOrder&&<WorkOrderDetail id={workOrder} auth={auth} materials={data.materiais||[]} user={me?.user} onClose={()=>setWorkOrder(null)} onSaved={m=>{setNotice(m);refresh()}}/>}{modal&&<Modal areas={data.areas||[]} title={modal.title} fields={modal.fields} initial={modal.initial} onClose={()=>setModal(null)} onSave={async f=>{let payload=f;if(modal.module==='checklists'&&f.itens_texto!==undefined)payload={...f,itens:String(f.itens_texto||'').split('\n').map(x=>({descricao:x.trim(),exige_foto:!!f.exige_foto})).filter(x=>x.descricao)};if(modal.module==='cotacoes'&&f.item1!==undefined)payload={titulo:f.titulo,itens:[{descricao:f.item1,quantidade:f.quantidade1,unidade:f.unidade1}]};return modal.onSave(payload)}}/>}</div>
}

function Panel({dash,go}){const m=dash.metrics||{};const items=[['OS abertas',m.os,HardHat,'os'],['Manutenções vencidas',m.manutencoes,Wrench,'manutencoes'],['Estoque baixo',m.estoque,Package,'estoque'],['Ocorrências abertas',m.ocorrencias,TriangleAlert,'ocorrencias'],['Documentos vencendo',m.documentos,FileText,'documentos'],['Contratos vencendo',m.contratos,ClipboardCheck,'documentos'],['Ferramentas emprestadas',m.ferramentas,Wrench,'ferramentas'],['Reservas próximas',m.reservas,CalendarDays,'reservas']];return <><section className="metrics">{items.map(([l,v,I,p])=><div className="metric" key={l} onClick={()=>go(p)} style={{cursor:'pointer'}}><div className="metric-top"><span>{l}</span><div className="metric-icon"><I/></div></div><strong>{v??0}</strong></div>)}</section><div className="grid2"><Card title="Pendências prioritárias" subtitle="Itens que precisam de atenção operacional."><div className="cardbody">{dash.alerts?.length?dash.alerts.map((a,i)=><div className="alertitem" key={i}><div><span className="strong">{a.tipo} {a.ref}</span><div className="muted">{a.titulo}</div></div><span className={badgeClass(a.prioridade)}>{cap(a.prioridade)}</span></div>):<Empty/>}</div></Card><Card title="Ações rápidas"><div className="quick"><button onClick={()=>go('os')}><strong>Abrir OS</strong><span>Manutenção corretiva</span></button><button onClick={()=>go('checklists')}><strong>Executar checklist</strong><span>Rotina operacional</span></button><button onClick={()=>go('ocorrencias')}><strong>Registrar ocorrência</strong><span>Protocolo e acompanhamento</span></button><button onClick={()=>go('cotacoes')}><strong>Nova cotação</strong><span>Comparar fornecedores</span></button><button onClick={()=>go('relatorios')}><strong>Livro da Gestão</strong><span>Relatório mensal PDF</span></button><button onClick={()=>go('reservas')}><strong>Reservas</strong><span>Áreas comuns</span></button></div></Card></div></>}
function Reports({openReport}){const reports=[['gestao_mensal','Livro da Gestão','Resumo mensal dos principais indicadores.'],['inventario','Inventário','Relação do patrimônio cadastrado.'],['itens_qr','Itens com QR','Itens identificados por QR Code.'],['estoque','Estoque','Saldos atuais e mínimos.'],['manutencoes','Manutenções','Planos e próximas execuções.'],['os','Ordens de serviço','OS, status, prioridades e custos.'],['ocorrencias','Ocorrências','Protocolos e resoluções.'],['documentos','Documentos','Validades e obrigações.'],['fornecedores','Fornecedores','Prestadores cadastrados.'],['reservas','Reservas','Evento, e-mail, horários, status e valores pagos/restantes.']];return <Card title="Relatórios disponíveis"><div className="cardbody"><div className="report-grid">{reports.map(([t,n,d])=><div className="report-card" key={t}><h3>{n}</h3><p>{d}</p><button className="btn light" onClick={()=>openReport(t)}>Gerar PDF</button></div>)}</div></div></Card>}
function SuperAdmin({rows,onNew,onEdit}){return <Card title="Condomínios clientes" subtitle="Ambientes independentes dentro da plataforma Soluções Condo." actions={<button className="btn primary small" onClick={onNew}><Plus size={15}/>Novo condomínio</button>}><Table rows={rows} columns={[{key:'nome',label:'Condomínio',render:r=><div className="stack"><span className="strong">{r.nome}</span><span className="muted">{r.cnpj}</span></div>},{key:'plano',label:'Plano',render:r=>cap(r.plano)},{key:'usuarios',label:'Usuários'},{key:'responsavel',label:'Responsável'},{key:'status',label:'Status',render:r=><span className={r.status==='ativo'?'badge green':r.status==='suspenso'?'badge orange':'badge red'}>{cap(r.status)}</span>}]} actions={r=><button className="btn light small" onClick={()=>onEdit(r)}><Pencil size={14}/>Alterar</button>}/></Card>}

function Admin({data,tab,setTab,openNew,openEdit,patch}){const cfg=data.configuracoes?.[0]||{};const tabs=[['config','Configurações'],['usuarios','Usuários'],['chaves','Chaves']];return <Card title="Administração"><div className="tabs">{tabs.map(([k,l])=><button className={`tab ${tab===k?'active':''}`} key={k} onClick={()=>setTab(k)}>{l}</button>)}</div>{tab==='config'&&<div className="cardbody"><div className="section-grid"><div><div className="muted">Nome do sistema</div><div className="strong">{cfg.nome_sistema||'—'}</div></div><div><div className="muted">Cor principal</div><div className="strong">{cfg.cor_primaria||'—'}</div></div><div><div className="muted">E-mail</div><div className="strong">{cfg.email||'—'}</div></div></div><div style={{marginTop:18}}><button className="btn primary small" onClick={()=>openEdit('Configurações',[{name:'nome_sistema',label:'Nome do sistema',required:true},{name:'cor_primaria',label:'Cor primária',type:'color'},{name:'endereco',label:'Endereço',full:true},{name:'telefone',label:'Telefone'},{name:'email',label:'E-mail',type:'email'},{name:'rodape_relatorio',label:'Rodapé dos relatórios',type:'textarea',full:true},{name:'mensagem_pedido',label:'Mensagem de pedido',type:'textarea',full:true}],'configuracoes',cfg)}><Pencil size={14}/>Alterar configurações</button></div></div>}{tab==='usuarios'&&<><div className="toolbar"><button className="btn primary small" onClick={()=>openNew('user','Novo usuário',[{name:'nome',label:'Nome',required:true},{name:'email',label:'E-mail',type:'email',required:true},{name:'senha',label:'Senha inicial',type:'password',help:'Mínimo de 6 caracteres para novos usuários. Se o e-mail já existir, o usuário será apenas vinculado.'},{name:'perfil',label:'Perfil',type:'select',default:'operacional',options:[{value:'admin',label:'Administrador'},{value:'gerente',label:'Gerente'},{value:'supervisor',label:'Supervisor'},{value:'operacional',label:'Operacional'},{value:'consulta',label:'Consulta'}]}],'usuarios')}><Users size={14}/>Novo usuário</button></div><Table rows={data.usuarios} columns={[{key:'nome',label:'Nome',render:r=><span className="strong">{r.nome}</span>},{key:'email',label:'E-mail'},{key:'perfil',label:'Perfil',render:r=>cap(r.perfil)},{key:'ativo',label:'Status',render:r=><span className={r.ativo?'badge green':'badge red'}>{r.ativo?'Ativo':'Inativo'}</span>}]} actions={r=><button className="btn light small" onClick={()=>patch('usuarios',{id:r.id,ativo:!r.ativo})}>{r.ativo?'Desativar':'Ativar'}</button>}/></>}{tab==='chaves'&&<><div className="toolbar"><button className="btn primary small" onClick={()=>openNew('key','Nova chave',[{name:'descricao',label:'Descrição'},{name:'max_usuarios',label:'Máximo de usuários',type:'number',default:20},{name:'expira_em',label:'Expira em',type:'datetime-local'}],'chaves')}><KeyRound size={14}/>Nova chave</button></div><Table rows={data.chaves} columns={[{key:'chave',label:'Chave',render:r=><code>{r.chave}</code>},{key:'descricao',label:'Descrição'},{key:'max_usuarios',label:'Limite'},{key:'expira_em',label:'Expiração',render:r=>datetime(r.expira_em)},{key:'ativa',label:'Status',render:r=><span className={r.ativa?'badge green':'badge red'}>{r.ativa?'Ativa':'Inativa'}</span>}]} actions={r=><button className="btn light small" onClick={()=>patch('chaves',{id:r.id,ativa:!r.ativa})}>{r.ativa?'Desativar':'Ativar'}</button>}/></>}</Card>}
